import{_ as e,o,c as s,a2 as r}from"./chunks/framework.O93z6AWZ.js";const m=JSON.parse('{"title":"Submit Assignment — English","description":"","frontmatter":{"title":"Submit Assignment — English"},"headers":[],"relativePath":"en/submit.md","filePath":"en/submit.md"}'),a={name:"en/submit.md"};function i(n,t,l,c,d,u){return o(),s("div",null,[...t[0]||(t[0]=[r('<h1 id="📤-submitting-your-project-to-the-class-repository" tabindex="-1">📤 Submitting Your Project to the Class Repository <a class="header-anchor" href="#📤-submitting-your-project-to-the-class-repository" aria-label="Permalink to &quot;📤 Submitting Your Project to the Class Repository&quot;">​</a></h1><blockquote><p>Once your team completes the project for your chosen topic (see the <a href="/hmyt-book/en/course_project">Course Project Bank</a>), submit it by opening a <strong>Pull Request</strong> to the shared class repository:</p><h2 id="👉-github-com-fossbk-spec-hmyt-project" tabindex="-1">👉 <a href="https://github.com/fossbk-spec/hmyt-project" target="_blank" rel="noreferrer">github.com/fossbk-spec/hmyt-project</a> <a class="header-anchor" href="#👉-github-com-fossbk-spec-hmyt-project" aria-label="Permalink to &quot;👉 [github.com/fossbk-spec/hmyt-project](https://github.com/fossbk-spec/hmyt-project)&quot;">​</a></h2></blockquote><p>This page only summarizes the process — the authoritative, up-to-date instructions always live in that repository&#39;s <code>CONTRIBUTING.md</code>. Read that file before submitting; this page may lag behind if the process changes.</p><hr><h2 id="_1-why-pull-requests-instead-of-email-drive" tabindex="-1">1. Why Pull Requests instead of email/Drive? <a class="header-anchor" href="#_1-why-pull-requests-instead-of-email-drive" aria-label="Permalink to &quot;1. Why Pull Requests instead of email/Drive?&quot;">​</a></h2><ul><li><strong>No team can overwrite another team&#39;s work</strong> — each PR may only touch its own team&#39;s folder; CI automatically blocks a PR that touches another folder.</li><li><strong>Clear history</strong> — every submission/revision is a commit; no risk of losing work or submitting the wrong version.</li><li><strong>Automated pre-checks before the instructor even looks</strong> — missing files, leftover placeholder values, or an accidentally committed API key are all caught at the CI step.</li></ul><h2 id="_2-5-steps-to-submit" tabindex="-1">2. 5 steps to submit <a class="header-anchor" href="#_2-5-steps-to-submit" aria-label="Permalink to &quot;2. 5 steps to submit&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">Step</th><th>What to do</th></tr></thead><tbody><tr><td style="text-align:center;"><strong>1</strong></td><td><strong>Fork</strong> <a href="https://github.com/fossbk-spec/hmyt-project" target="_blank" rel="noreferrer"><code>hmyt-project</code></a> to your team&#39;s GitHub account</td></tr><tr><td style="text-align:center;"><strong>2</strong></td><td>Create branch <code>submit/&lt;topic_slug&gt;-&lt;team_code&gt;</code>, copy <code>submissions/_TEMPLATE/</code> into <code>submissions/&lt;topic_slug&gt;_&lt;team_code&gt;/</code></td></tr><tr><td style="text-align:center;"><strong>3</strong></td><td>Fill in <code>submission.json</code> (topic id, team code, student IDs) + report (<code>report/</code>) + source code (<code>src/</code>)</td></tr><tr><td style="text-align:center;"><strong>4</strong></td><td>Run the local check: <code>python scripts/validate_submission.py submissions/&lt;topic_slug&gt;_&lt;team_code&gt;</code> — must show <code>[PASSED]</code></td></tr><tr><td style="text-align:center;"><strong>5</strong></td><td>Push to your fork, open a <strong>Pull Request</strong> to <code>main</code> of <code>hmyt-project</code>, wait for CI ✅ and instructor/TA review</td></tr></tbody></table><p><code>topic_slug</code> is the topic name as it appears in your topic&#39;s page URL, e.g. topic <a href="/hmyt-book/en/du_an/suy_tim_risk_dxai">3.4 Heart Failure — accelerated</a> → slug is <code>suy_tim_risk_dxai</code>.</p><h2 id="_3-mandatory-rules-ci-blocks-the-pr-if-violated" tabindex="-1">3. Mandatory rules (CI blocks the PR if violated) <a class="header-anchor" href="#_3-mandatory-rules-ci-blocks-the-pr-if-violated" aria-label="Permalink to &quot;3. Mandatory rules (CI blocks the PR if violated)&quot;">​</a></h2><ol><li><strong>No real patient data</strong> — use only public datasets (MIMIC/PTB-XL/PhysioNet/UCI...) or simulated data, per the <a href="/hmyt-book/en/course_project">Management Framework &amp; Rubric</a>.</li><li><strong>No API keys/tokens/passwords/<code>.env</code> files.</strong></li><li><strong>Use student IDs, not full names</strong> in <code>submission.json</code> or any file — this repository is permanently public on GitHub.</li><li><strong>Large data files (&gt;10MB)</strong> go on Google Drive/Kaggle/HuggingFace — link them in your submission&#39;s <code>README.md</code> instead.</li><li><strong>1 Pull Request = 1 folder</strong> — never combine multiple teams&#39; changes in one PR.</li></ol><h2 id="_4-faq" tabindex="-1">4. FAQ <a class="header-anchor" href="#_4-faq" aria-label="Permalink to &quot;4. FAQ&quot;">​</a></h2><p><strong>Can we resubmit after merge?</strong> Not through a normal PR (branch protection prevents overwriting any folder, including your own, after merge, to preserve submission integrity) — contact the instructor directly for resubmissions.</p><p><strong>Where do I see why CI failed?</strong> Open the &quot;Checks&quot; tab on your Pull Request — the log lists the exact offending line/file.</p><div class="tip custom-block"><p class="custom-block-title">Read more</p><p>Full details, examples, and extended FAQ live in <a href="https://github.com/fossbk-spec/hmyt-project/blob/main/CONTRIBUTING.md" target="_blank" rel="noreferrer"><code>CONTRIBUTING.md</code></a> of the <code>hmyt-project</code> repository.</p></div>',15)])])}const p=e(a,[["render",i]]);export{m as __pageData,p as default};
